  where kind = 'course_overview') = $expected_content$[{"itemId":"ce24b613-5845-53a2-a748-815347fbc945","courseId":"40000000-0000-4000-8000-000000000001","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Entrepreneurship and Innovation","body":"Introduction to entrepreneurship and innovation, from recognising opportunities and developing business ideas to funding and launching new ventures, and entrepreneurship's role in economic development.","topics":[{"chapter":"1-2","description":"Meaning of Entrepreneurship & Types of Entrepreneurs"},{"chapter":"3-4","description":"Innovation and Opportunity Recognition"},{"chapter":"5-6","description":"Business Ideas and Concept Development"},{"chapter":"7-8","description":"Funding Sources and Business Creation"},{"chapter":"9","description":"Role of Entrepreneurship in Economic Development"}],"examFocus":["Definitions of entrepreneurship and innovation","Types of entrepreneurs and their characteristics","Opportunity recognition process","Business idea evaluation","Short essay questions on economic impact","Theoretical frameworks and concepts"]}}]$expected_content$::jsonb,
