  where kind = 'course_overview') = $expected_content$[{"itemId":"58dca9fe-1102-567a-bae2-6dec6a9b89a2","courseId":"40000000-0000-4000-8000-000000000003","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Business Statistics","body":"Data collection, analysis, and interpretation techniques including graphs, tables, statistical measures, probability distributions, and their application in business decision-making.","topics":[{"chapter":"1-2","description":"Data Collection Methods and Types"},{"chapter":"3-4","description":"Graphs, Tables, and Data Visualization"},{"chapter":"5-6","description":"Central Tendency: Mean, Median, Mode"},{"chapter":"7-8","description":"Dispersion: Variance and Standard Deviation"},{"chapter":"9-10","description":"Probability and Distributions"}],"examFocus":["Data collection and sampling techniques","Calculation of mean, median, mode","Standard deviation and variance calculations","Probability distributions","Problem-solving with formulas","Interpretation of statistical results"]}}]$expected_content$::jsonb,
