    where i.course_id = '40000000-0000-4000-8000-000000000006' and i.published_revision is not null) published
  where kind = 'cbt_question') = $expected_content$[{"itemId":"4f30ad18-a227-52ec-8530-1387b4a0cda7","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"b2cbe46b-eb1b-426c-add7-a9cdfcc11447","sourceKey":"quiz:1","parentItemId":null,"revision":1,"payload":{"prompt":"Consumer behaviour is best defined as:","options":["The study of how companies manipulate people","The behavior consumers display in searching for, purchasing, using, and disposing of products","The mathematical calculation of price elasticity","The psychology of employee management"],"correctOption":1,"section":"Introduction to Consumer Behaviour"}},{"itemId":"b4fc986f-3183-5bbf-b7a3-b4999979763e","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"9a3a0e79-2c1f-4440-b0e8-714376071704","sourceKey":"quiz:10","parentItemId":null,"revision":1,"payload":{"prompt":"Post-purchase behaviour is critical because:","options":["It has no impact on future sales","Satisfied customers become loyal and generate positive word-of-mouth","Consumers always forget their purchases","It only matters for expensive items"],"correctOption":1,"section":"Decision-Making Process"}},{"itemId":"5e33bd76-79dc-58a1-a591-c0095d692e88","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"a629492a-9832-48e5-8358-649c8ab586e5","sourceKey":"quiz:11","parentItemId":null,"revision":1,"payload":{"prompt":"Culture is the broadest influence on consumer behaviour because it dictates:","options":["Only language","Fundamental tastes, norms, values, and traditions","Nothing important","Only clothing choices"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"4dd2f91d-faea-52d1-bd29-7c397ab9c4f0","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"7455a373-5a00-42b0-b027-74f5e48b312c","sourceKey":"quiz:12","parentItemId":null,"revision":1,"payload":{"prompt":"A sub-culture is:","options":["The main culture of a country","A smaller group within a culture providing specific identification (nationality, religion, region)","A group with no culture","Only applicable to rural areas"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"296b2a8e-f1b1-5e82-b012-c4f705f0be20","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"da327322-fd8e-4c31-adbb-955f91ff8957","sourceKey":"quiz:13","parentItemId":null,"revision":1,"payload":{"prompt":"Social class affects consumer behaviour through:","options":["No impact whatsoever","Wealth, education, values influencing media consumption and product choices","Only job title","Physical appearance"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"eed9cdf0-4890-53ed-bfa2-c724fa99f6a6","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"1c1d9485-0552-494e-927d-823dc331696e","sourceKey":"quiz:14","parentItemId":null,"revision":1,"payload":{"prompt":"Reference groups are:","options":["Groups used as a standard for evaluating one's own behavior or purchasing decisions","Groups with no influence","Only family members","Fictional characters"],"correctOption":0,"section":"Group & Cultural Influences"}},{"itemId":"f364eb86-6c44-534c-b486-9281c9e847e8","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"18600cc3-097d-484d-8e98-86797786babe","sourceKey":"quiz:15","parentItemId":null,"revision":1,"payload":{"prompt":"Aspirational groups are:","options":["Groups a person actively avoids","Groups a person wants to join or emulate","Groups with no members","Family only"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"7bce537b-beac-501a-a252-94a89cf35fe6","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"0332336e-b916-49d5-9682-6a79206f5975","sourceKey":"quiz:16","parentItemId":null,"revision":1,"payload":{"prompt":"Informational influence occurs when:","options":["A person ignores all advice","A person seeks explicit expert opinions (e.g., doctor, mechanic)","A person buys randomly","A person avoids information"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"543a6b4b-430e-5db3-9d47-38cd3dd24807","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"cda87dd8-74c4-40e0-8476-5b52eb7da3b6","sourceKey":"quiz:17","parentItemId":null,"revision":1,"payload":{"prompt":"Utilitarian (Normative) influence involves:","options":["Independent decision-making","Buying something to fit in or be rewarded/avoid punishment by friends or family","Avoiding all social groups","Only considering price"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"cd965a3e-7758-52f4-aced-556b2ddae895","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"938f0ada-d2f4-4144-8778-9ad7c1a7a5c5","sourceKey":"quiz:18","parentItemId":null,"revision":1,"payload":{"prompt":"Value-expressive influence means:","options":["Ignoring group values","Adopting values of a group to enhance self-image (e.g., buying eco-friendly products)","Expressing anger","Hiding your values"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"d9ab01fc-ee90-5b7f-bf03-5f39c2335dba","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"3048441c-34b5-4460-ae1b-a53792a44faa","sourceKey":"quiz:19","parentItemId":null,"revision":1,"payload":{"prompt":"Social stratification (social class) is typically measured using:","options":["Height and weight","Occupation, income, and education","Favorite color","Shoe size"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"fc979dbb-b10a-5777-8b21-f6b63ce498fc","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"33a0df98-c0b8-464a-9780-2a08831369bf","sourceKey":"quiz:2","parentItemId":null,"revision":1,"payload":{"prompt":"What is the difference between a consumer and a customer?","options":["There is no difference","A customer purchases the product; a consumer is the end-user who benefits from it","A consumer always pays more","A customer never uses the product"],"correctOption":1,"section":"Introduction to Consumer Behaviour"}},{"itemId":"b3e2a5fb-ae17-575d-bb34-f9afee36205d","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"9edc6c71-290c-4d1c-a427-dea79a903930","sourceKey":"quiz:20","parentItemId":null,"revision":1,"payload":{"prompt":"Opinion leaders are individuals who:","options":["Work for the government only","Influence the opinions and behaviors of others regarding specific product categories","Never share their opinions","Only buy expensive products"],"correctOption":1,"section":"Group & Cultural Influences"}},{"itemId":"7317a8eb-04b1-5b8a-a1a1-05fc1978bcf9","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"49b5fd45-8959-40f3-8915-d91cf9213381","sourceKey":"quiz:21","parentItemId":null,"revision":1,"payload":{"prompt":"According to Maslow's Hierarchy of Needs, which need must be satisfied first?","options":["Self-actualization","Physiological needs (food, water)","Esteem needs","Social needs"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"08dd09c2-b6ce-5968-9b97-95d1ca50e86d","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"fd766262-d42b-495e-bba4-8ea46e836feb","sourceKey":"quiz:22","parentItemId":null,"revision":1,"payload":{"prompt":"Motivation is best described as:","options":["The final purchase act","The driving force within individuals that impels them to action","A set of advertisements","The price consumers pay"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"8176c440-f19d-5e10-a081-110b4af6760c","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"27e90ae1-8ca6-4b78-8947-b972d9e95fcd","sourceKey":"quiz:23","parentItemId":null,"revision":1,"payload":{"prompt":"Selective attention means consumers:","options":["Pay attention to everything","Screen out most stimuli and only notice what is relevant to them","Never pay attention","Only notice expensive products"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"e13f615d-425b-5530-948b-8aa8ad567b3d","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"424a158b-1d27-4368-8ef8-40280ce90f6f","sourceKey":"quiz:24","parentItemId":null,"revision":1,"payload":{"prompt":"Selective distortion occurs when consumers:","options":["Remember everything accurately","Twist or interpret information to fit their existing preconceptions","Ignore all information","Only buy one brand"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"0ca5a1d6-71e9-5046-8fdf-2da4fc280048","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"46326cf6-4f9b-430a-b10b-adc00f6f11b2","sourceKey":"quiz:25","parentItemId":null,"revision":1,"payload":{"prompt":"Selective retention means consumers:","options":["Remember everything equally","Tend to remember good points about products they like and forget good points about competitors","Have perfect memory","Never remember any advertisements"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"5446b422-5c45-59b3-8da2-947bda3acd82","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"4277ede5-5949-421d-acdf-6c34f9cce314","sourceKey":"quiz:26","parentItemId":null,"revision":1,"payload":{"prompt":"Classical conditioning involves:","options":["Complex problem-solving","Learning to associate a brand with a specific positive stimulus (like music or imagery)","Ignoring all advertisements","Genetic inheritance"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"c461eea7-ce41-59b3-acd0-6f214727ef33","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"a7571f0d-451a-4e21-a278-4f7f91372013","sourceKey":"quiz:27","parentItemId":null,"revision":1,"payload":{"prompt":"Instrumental (Operant) conditioning occurs when:","options":["Consumers are punished for purchases","A consumer is rewarded for specific behavior (e.g., loyalty points)","Consumers forget brands","No learning occurs"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"fddaa8b3-1417-5882-bebf-2c319cf1f71c","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"e6a0d33a-84d0-460a-ae2a-5e63f5b6e4c7","sourceKey":"quiz:28","parentItemId":null,"revision":1,"payload":{"prompt":"The Tri-component Attitude Model consists of:","options":["Price, Place, Promotion","Cognitive, Affective, Conative components","Past, Present, Future","Internal, External, Neutral"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"18fb1965-bda7-5426-8fec-c64dbc28a8f7","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"5ca71946-d39f-40b8-a2b5-a54ac684d85c","sourceKey":"quiz:29","parentItemId":null,"revision":1,"payload":{"prompt":"The conative component of attitude refers to:","options":["What a person knows about a brand","How a person feels about a brand","The likelihood that a person will take action (purchase)","Brand logo design"],"correctOption":2,"section":"Individual Psychology"}},{"itemId":"3a49a05d-9493-5ccb-ba1a-8cd3d53d6ec5","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"65eaf7dc-0e38-443d-91dc-5f68618cb2a2","sourceKey":"quiz:3","parentItemId":null,"revision":1,"payload":{"prompt":"Impulse buyers are characterized by:","options":["Extensive research before purchase","Spontaneous buying based on emotion","Always buying the cheapest option","Never making purchases"],"correctOption":1,"section":"Introduction to Consumer Behaviour"}},{"itemId":"0a04b808-05a4-5994-a329-42888b845fcc","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"31595d44-38d7-4216-b2a9-8f0f3c51fe1b","sourceKey":"quiz:30","parentItemId":null,"revision":1,"payload":{"prompt":"Cognitive dissonance occurs:","options":["Before making a purchase","When a consumer experiences post-purchase tension or regret","Never","Only with free products"],"correctOption":1,"section":"Individual Psychology"}},{"itemId":"084a21e2-0f70-5593-bdff-9c2a7c273a93","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"aeba837c-8dee-4b1d-a63f-8d9aa46c634c","sourceKey":"quiz:31","parentItemId":null,"revision":1,"payload":{"prompt":"Communication is best defined as:","options":["Only written messages","Transmission of a message from sender to receiver through a medium","Talking to yourself","Silence"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"4842f93b-c924-51aa-a890-dc004384f875","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"90044d2a-6ce1-4d50-b5da-0c48c057c758","sourceKey":"quiz:32","parentItemId":null,"revision":1,"payload":{"prompt":"The five components of communication are:","options":["Price, Product, Place, Promotion, People","Sender, Message, Medium, Receiver, Feedback","Past, Present, Future, Now, Later","Yes, No, Maybe, Always, Never"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"b665c66d-5173-5750-a32d-a3cffef77f06","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"56e30cd0-ca9c-4e4a-ad27-529666aea6d7","sourceKey":"quiz:33","parentItemId":null,"revision":1,"payload":{"prompt":"Why do informal sources (friends/family) typically have higher credibility than formal sources (advertisers)?","options":["They are smarter","Consumers perceive them as having nothing to gain financially from the recommendation","They are louder","They have better education"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"d2c7c4c5-61d1-57d5-8816-0994b525ddbf","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"19b193d3-6b03-48ef-b141-a68eb706a4ca","sourceKey":"quiz:34","parentItemId":null,"revision":1,"payload":{"prompt":"Psychological noise in communication refers to:","options":["Loud sounds","Competing advertising messages and distractions","Music in stores","Silence"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"ac4fb4ac-4b59-5b24-97fa-8d6fff6cba2a","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"fdd65df0-488d-4c90-b4f8-172aef57c54a","sourceKey":"quiz:35","parentItemId":null,"revision":1,"payload":{"prompt":"Marketers overcome communication barriers by:","options":["Giving up","Repeating messages and using highly credible spokespersons","Hiding information","Reducing product quality"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"9ce93da5-fa2a-58bd-89c0-4f234817aed9","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"d8cf05f9-85ce-4f07-bd59-a0185d24a615","sourceKey":"quiz:36","parentItemId":null,"revision":1,"payload":{"prompt":"Which promotional tool was determined to be best suited for Nigerian insurance companies in the AHP study?","options":["Sales Promotion","Advertising","Sponsorship","Direct Marketing"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"6bcb175f-ae89-5e81-8400-f2207a94d29f","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"7a402017-4ca5-4eb4-9428-d24afdaef69e","sourceKey":"quiz:37","parentItemId":null,"revision":1,"payload":{"prompt":"Personal selling is particularly effective because it:","options":["Is the cheapest form","Involves direct relationships and builds buyer conviction","Requires no training","Is non-personal communication"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"e863a575-07a3-5d84-aeda-70b7ad9b43e9","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"9583f7e4-f94b-46eb-a4e9-bc5e7de8fcf3","sourceKey":"quiz:38","parentItemId":null,"revision":1,"payload":{"prompt":"The main function of promotion is to:","options":["Distract consumers","Inform and persuade the target market to act positively","Reduce quality","Replace product development"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"47a18fac-d6eb-5c03-aeb4-3a06eca0d08d","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"16a75955-9be8-4184-86e2-a01589c27ddf","sourceKey":"quiz:39","parentItemId":null,"revision":1,"payload":{"prompt":"Advertising is considered a:","options":["Personal communication form","Non-personal communication form","Private conversation","Secret message"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"a18d83c8-0d0e-5118-afff-f738fbdbf0af","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"a8e5c684-4281-45c8-907c-4d5c84682a76","sourceKey":"quiz:4","parentItemId":null,"revision":1,"payload":{"prompt":"Brand loyal buyers will:","options":["Switch brands for any discount","Stick to trusted brands regardless of price","Never buy the same product twice","Only shop online"],"correctOption":1,"section":"Introduction to Consumer Behaviour"}},{"itemId":"c16a59bc-495e-5511-bb73-fca0e6b8dea9","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"30a760f2-f22e-4903-871e-eaaeb3424a92","sourceKey":"quiz:40","parentItemId":null,"revision":1,"payload":{"prompt":"Publicity is defined as information that is:","options":["Always paid for by the organization","Not directly paid for by the organization","Only in newspapers","Never shared"],"correctOption":1,"section":"Communication & Persuasion"}},{"itemId":"1b57bd7e-d252-5281-82aa-116cae105783","courseId":"40000000-0000-4000-8000-000000000006","kind":"cbt_question","questionId":"80eb9b36-06d3-4f53-83b8-19cd82fcc884","sour