  where kind = 'cbt_question') = $expected_content$[{"itemId":"0fdbdf02-46d0-5102-bf1a-9b4603de5603","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"474fbb73-ef2e-4540-8c96-a46c588c9d51","sourceKey":"quiz:1","parentItemId":null,"revision":1,"payload":{"prompt":"What is listening?","options":["Speaking clearly to others","Receiving, perceiving, and decoding spoken words","Writing down key points during a lecture","Memorizing information verbatim"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"13d3ee2a-5e0d-5811-8460-6da5a535f902","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"abb96494-ec72-402f-a82c-b1b5e25ff199","sourceKey":"quiz:10","parentItemId":null,"revision":1,"payload":{"prompt":"Maintaining eye contact helps in listening because it:","options":["Distracts the lecturer","Links the listener's mind with the speaker's","Reduces note-taking time","Encourages multitasking"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"c2d905dc-6c49-5318-aa0c-4bf9d0a6c371","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"32269e54-f0a0-4726-8e56-96feff4a2975","sourceKey":"quiz:100","parentItemId":null,"revision":1,"payload":{"prompt":"The French statute of 1351 allowed wage increases up to:","options":["50%","One-third","10%","No increase"],"correctOption":1,"section":"Comprehension & Summary"}},{"itemId":"fdb54fdd-ec38-5c1b-8514-1e5d35eb4797","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"742ebce6-17f9-48c2-b821-210e563be5c0","sourceKey":"quiz:11","parentItemId":null,"revision":1,"payload":{"prompt":"To enhance listening, you should:","options":["Focus on the lecturer's dressing","Repress emotional biases","Write every word verbatim","Avoid mental questions"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"2f5ce2b2-bd56-5bbf-b90f-411d94a6ef87","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a9546cfe-4105-49cf-8df9-8bd84a840b69","sourceKey":"quiz:12","parentItemId":null,"revision":1,"payload":{"prompt":"Which strategy involves speculating about the lecture's main thrust?","options":["Avoiding distractions","Asking mental questions","Using shorthand","Maintaining eye contact"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"bb8b130d-5bf4-5985-86d6-8508c8afb9cd","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"1bc54a60-8703-470e-ad9a-d8a43a188426","sourceKey":"quiz:13","parentItemId":null,"revision":1,"payload":{"prompt":"Effective listening requires seeing it as a:","options":["Passive activity","Mental challenge","Religious duty","Social obligation"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"75c98684-b4e5-5ab9-aed5-421dacd2eaa7","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"ea8f6f1e-f709-4273-9097-f88841cc130c","sourceKey":"quiz:14","parentItemId":null,"revision":1,"payload":{"prompt":"Which is a distraction to avoid during lectures?","options":["Lecturer's gestures","Friends talking","Note taking","Summarizing"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"31036258-faaf-56db-86d5-5a1ab5a527a5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"372b6939-1b7d-4173-ae30-a23b6f980adb","sourceKey":"quiz:15","parentItemId":null,"revision":1,"payload":{"prompt":"Formal listening is typically used in:","options":["Casual conversations","University lectures","Social media chats","Family gatherings"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"0af1cfb0-1e70-5d64-83df-8adc188fe1c0","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a21f5126-4b57-4363-af76-ba7e9570707d","sourceKey":"quiz:16","parentItemId":null,"revision":1,"payload":{"prompt":"A key purpose of formal listening is to:","options":["Criticize a friend's argument","Comprehend and evaluate academic content","Discuss weekend plans","Memorize song lyrics"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"b34ae6e7-7252-5b5b-a157-0318fa4210f4","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8ce36a2f-66eb-48a4-9504-e7bc23e6a24b","sourceKey":"quiz:17","parentItemId":null,"revision":1,"payload":{"prompt":"Informal listening is essential for:","options":["Passing exams","Improving societal relationships","Writing research papers","Laboratory experiments"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"1f2879ad-20d0-526d-beb6-41356799d479","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"00bf255c-0598-48f8-a7eb-023629ff748e","sourceKey":"quiz:18","parentItemId":null,"revision":1,"payload":{"prompt":"Which activity involves informal listening?","options":["Attending a seminar","Chatting with a friend","Taking lecture notes","Analyzing a scientific theory"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"65659aec-da9e-53ed-babb-3e0660680f19","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"5d21a398-a957-4f4b-acd7-eab81013cc38","sourceKey":"quiz:19","parentItemId":null,"revision":1,"payload":{"prompt":"Effective note taking requires the ability to:","options":["Write verbatim","Recognize main ideas","Ignore references","Avoid paraphrasing"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"44c557af-743a-5a97-83f2-9eae2721caff","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"e99e36ad-b945-4ca9-802c-bbb677de7083","sourceKey":"quiz:2","parentItemId":null,"revision":1,"payload":{"prompt":"Effective listening is crucial for:","options":["Passing exams only","Academic success and improving societal relationships","Avoiding eye contact with lecturers","Multitasking during lectures"],"correctOption":1,"section":"Listening Skills"}},{"itemId":"8ba6d3dd-05db-5a19-8a4d-df6bc45f2f08","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2130e349-bca9-4b5d-8744-3bbc78974c02","sourceKey":"quiz:20","parentItemId":null,"revision":1,"payload":{"prompt":"Which is a requirement for note taking?","options":["Using only textbook formats","Including irrelevant details","Creating a personal recording system","Avoiding abbreviations"],"correctOption":2,"section":"Listening Skills"}},{"itemId":"e144bc88-0b6c-5479-94d3-10ef0bbbbd0b","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"b9053881-8306-4399-b5b1-d7022d31b38a","sourceKey":"quiz:21","parentItemId":null,"revision":1,"payload":{"prompt":"Which organ is responsible for initiating the airstream for speech?","options":["Larynx","Lungs","Tongue","Diaphragm"],"correctOption":1,"section":"The Sounds of English"}},{"itemId":"30f52d32-d952-5553-b03d-0cc8a61768a5","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"2cc5dccc-6f49-47f8-a6cb-b67083d9d737","sourceKey":"quiz:22","parentItemId":null,"revision":1,"payload":{"prompt":"The vocal folds are located in the:","options":["Pharynx","Larynx","Nasal Cavity","Alveolar Ridge"],"correctOption":1,"section":"The Sounds of English"}},{"itemId":"8106b8c9-9e95-56fa-814b-9dfed64b6e38","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"8670d60b-0b96-489b-ab81-8586eacae13e","sourceKey":"quiz:23","parentItemId":null,"revision":1,"payload":{"prompt":"The most flexible active articulator is the:","options":["Lips","Tongue","Velum","Teeth"],"correctOption":1,"section":"The Sounds of English"}},{"itemId":"0c0a6eb6-06eb-5e43-a65c-a10615c602ab","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"a2efc128-7491-44cf-a819-4a6c401c86c4","sourceKey":"quiz:24","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is a passive articulator?","options":["Lips","Tongue","Hard Palate","Velum"],"correctOption":2,"section":"The Sounds of English"}},{"itemId":"d0e3dbc3-d5db-5fdb-98bd-bb9a865c248d","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"95dfffa2-09e8-45d8-b968-f2d688240b83","sourceKey":"quiz:25","parentItemId":null,"revision":1,"payload":{"prompt":"The soft palate/velum controls airflow into the:","options":["Oral Cavity","Nasal Cavity","Pharynx","Larynx"],"correctOption":1,"section":"The Sounds of English"}},{"itemId":"46530274-f8db-58ff-8321-f25c31d04239","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"512606be-f032-4ac3-909c-012efac1bd37","sourceKey":"quiz:26","parentItemId":null,"revision":1,"payload":{"prompt":"/p/ and /b/ are classified as:","options":["Velar stops","Alveolar fricatives","Bilabial stops","Glottal fricatives"],"correctOption":2,"section":"The Sounds of English"}},{"itemId":"152b4549-cd16-52fb-870a-0157306fbe27","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"309dce4a-4dd7-459a-ac42-5950d5e67cce","sourceKey":"quiz:27","parentItemId":null,"revision":1,"payload":{"prompt":"The sound /θ/ (as in \"thin\") is a:","options":["Voiced dental fricative","Voiceless dental fricative","Voiced alveolar fricative","Voiceless palatal fricative"],"correctOption":1,"section":"The Sounds of English"}},{"itemId":"8c2fd029-f45a-5e72-b617-5d6b5c41a581","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"81ab7294-32f1-4e72-a4f5-51a217223ede","sourceKey":"quiz:28","parentItemId":null,"revision":1,"payload":{"prompt":"Which consonant is a voiced palato-alveolar affricate?","options":["/tʃ/","/dʒ/","/ʃ/","/ʒ/"],"correctOption":1,"section":"The Sounds of English"}},{"itemId":"bffa04b2-986d-567f-9bc6-9e03c729de0c","courseId":"40000000-0000-4000-8000-000000000008","kind":"cbt_question","questionId":"d28a2905-544d-4be2-88b0-a1787c3187df","sourceKey":"quiz:29","parentItemId":null,"revision":1,"p