  where kind = 'cbt_question') = $expected_content$[{"itemId":"8acb15cb-763c-5bde-963c-569098304819","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ccb72f45-30e7-41b2-9b06-c44dc5bcd53c","sourceKey":"quiz:1","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following expresses a constraint in Linear Programming, e.g. ‘labour ≤ 100 hours’?","options":["Simultaneous equation","Logarithm","Linear equation","Linear inequality"],"correctOption":3,"section":"Section A — Basic Mathematical Concepts for Management"}},{"itemId":"229ffed6-0011-5ba4-a1cc-0a0878fb24f9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"30ed641b-d9dd-421b-84db-caddc564da70","sourceKey":"quiz:10","parentItemId":null,"revision":1,"payload":{"prompt":"In the Product Mix worked example (Tables at ₦20,000, Chairs at ₦10,000, 200 total products, ₦2,800,000 total profit), how many Tables were sold?","options":["90","60","80","70"],"correctOption":2,"section":"Section A — Basic Mathematical Concepts for Management"}},{"itemId":"917371db-42ff-5629-93ba-a88bf4c5f5fc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ce81f5bc-b985-43c0-ab87-ba081a5c8ced","sourceKey":"quiz:100","parentItemId":null,"revision":1,"payload":{"prompt":"Which of these is NOT one of the 5 approaches to decision making listed in the class notes?","options":["Voting","Experience","Intuition","Regression analysis"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"a3902a59-a245-54a1-a168-fa3ca97652ab","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f33b467b-5d60-4dfa-962d-37578fff6b3b","sourceKey":"quiz:101","parentItemId":null,"revision":1,"payload":{"prompt":"Decision Theory is defined (per class notes) as:","options":["A qualitative-only approach with no data","An analytic and systematic approach to studying decision making, using a rational process for selecting the best of several alternatives","A purely mathematical formula with no room for judgement","A method used only for financial forecasting"],"correctOption":1,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"45c361af-4ea1-5635-a00f-6f0027c799f6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c53feb47-149b-4f89-8905-9f981bd9700b","sourceKey":"quiz:102","parentItemId":null,"revision":1,"payload":{"prompt":"Variables under the control of the decision maker, also called alternatives/options, are:","options":["Controllable variables","Exogenous variables","Uncontrollable variables","State of nature"],"correctOption":0,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"b9d123a8-003c-5f2c-8e93-3c9568aa2be1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"58ee0ab0-136b-44fb-b326-1d79d998e791","sourceKey":"quiz:103","parentItemId":null,"revision":1,"payload":{"prompt":"Variables that are NOT under the control of the decision maker, but can influence the decision, are called:","options":["Performance measures","Controllable variables","Decision variables","Uncontrollable variables"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"8bcc08f9-09e0-54f6-9625-1de265d20775","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1c0aaf13-62c4-4750-a326-f6a4c9454bf6","sourceKey":"quiz:104","parentItemId":null,"revision":1,"payload":{"prompt":"In which decision-making environment is all information about the uncontrollable variable known for certainty?","options":["Ambiguity","Certainty","Uncertainty","Stochastic / Risk"],"correctOption":1,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"f30dc0f2-5e1f-5243-82c3-69d3b70fc94f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"db5f5270-c56f-4cb9-a31f-959eaee45ddb","sourceKey":"quiz:105","parentItemId":null,"revision":1,"payload":{"prompt":"In which decision-making environment is the occurrence of the uncontrollable variable unknown, but its likelihood is known?","options":["Certainty","Uncertainty","Determinism","Stochastic / Risk"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"34aa0939-65eb-5be0-8f27-64a5c019b643","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7754b9af-8265-4944-be69-acff6166067e","sourceKey":"quiz:106","parentItemId":null,"revision":1,"payload":{"prompt":"In which decision-making environment can you NOT ascribe a probability to the uncontrollable variable's occurrence?","options":["Certainty","Stochastic / Risk","Determinism","Uncertainty"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"98d9c2c8-9349-5a04-a35f-73caa89f506d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"efb2db38-d4ce-443d-9a03-6acd329219a3","sourceKey":"quiz:107","parentItemId":null,"revision":1,"payload":{"prompt":"Which element of decision making refers to “making a choice out of different options”?","options":["Action","State of Nature","Payoff","Alternatives"],"correctOption":0,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"06088287-f4f0-5415-a0f0-3d75fa21d1be","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"2fcb1f40-e4ac-4e49-bd79-d20e57388eb7","sourceKey":"quiz:108","parentItemId":null,"revision":1,"payload":{"prompt":"Which element of decision making refers to the uncontrollable decision variables?","options":["Alternatives","Payoff","Action","State of Nature"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"2a052665-c36a-5de1-95c3-b9a86b5b3da8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8c02cb5a-152f-468e-84cd-bc956d1cf2ca","sourceKey":"quiz:109","parentItemId":null,"revision":1,"payload":{"prompt":"Which element of decision making refers to the benefits accrued to you for making a decision?","options":["Payoff","Goal / Objectives","Action","State of Nature"],"correctOption":0,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"658bdea9-bc7b-5da2-bd83-13bad259ce4d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"89145f05-2a1e-44da-a307-c1bb8ef2212a","sourceKey":"quiz:11","parentItemId":null,"revision":1,"payload":{"prompt":"An investment of ₦1,000,000 grows at 10% annually (class example). What is its future value after 3 years?","options":["₦1,100,000","₦1,331,000","₦1,300,000","₦1,310,000"],"correctOption":1,"section":"Section A — Basic Mathematical Concepts for Management"}},{"itemId":"556f7a02-0601-5e4a-bad7-2f85f76b5562","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"0de1148a-7d1b-40a0-a448-007dada9db0f","sourceKey":"quiz:110","parentItemId":null,"revision":1,"payload":{"prompt":"In the detailed 9-stage decision-making process (class notes), which stage comes immediately after “Gather Information”?","options":["Identify the possible outcomes","Definition of the decision problem","Screening Alternative Courses of Action","Evaluate the result"],"correctOption":2,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"5b09d607-3c19-5de2-9e51-09af783a24cb","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"961933ac-bc5f-4201-89f6-832acc24a53c","sourceKey":"quiz:111","parentItemId":null,"revision":1,"payload":{"prompt":"Which is the LAST of the 9 stages in the decision-making process (class notes)?","options":["Analysis of physical/alternative actions","Selection of best optimal action","Evaluate the result","Implementation of decision"],"correctOption":2,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"8727be62-80a2-58ea-8e6a-a727f23089f6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e6541204-debe-4939-a1e5-221a27ac0935","sourceKey":"quiz:112","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) What payoff does the Full product line generate under a Poor market?","options":["18,000","(2,000)","15,000","4,000"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"7f44364a-e3a4-57a8-9dde-12c99d42247e","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f0973a85-bac0-42b4-ad07-114794646f29","sourceKey":"quiz:113","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) What payoff does the Minimal product line generate under a Moderate market?","options":["4,000","18,000","(500)","6,000"],"correctOption":2,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"5badc7aa-ceb0-53c0-bfb2-e1da5e7ac6f8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"09e14f21-d111-4839-b27b-897e4551f987","sourceKey":"quiz:114","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) Using the Maximax criterion, which product line(s) should be chosen?","options":["Partial only, at 18,000","Minimal only","Full only, at 15,000","Full or Partial (tied at 20,000)"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"c55b63b8-6233-5dea-9b10-ad40c6c5da8b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"1173eb00-0510-4edd-b963-21730cc42854","sourceKey":"quiz:115","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) Using the Maximin criterion, which product line should be chosen?","options":["Partial","Minimal","Full","All three are tied"],"correctOption":0,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"c855def3-58cd-5cd2-abfc-b6315441f0cc","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8c836d5b-b270-4ab8-acd1-610973c54411","sourceKey":"quiz:116","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) What is Partial's row minimum (used in the Maximin calculation)?","options":["1,000","(500)","500","(2,000)"],"correctOption":2,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"5378b524-dddd-5aba-aa2c-7ca7c3d4d85f","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6b5454ff-565f-48a0-b4f3-d90630d501e2","sourceKey":"quiz:117","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) Using the Laplace criterion (average of each row, equal weighting), what is the average payoff for the Full product line?","options":["₦8,500","₦9,250","₦6,875","₦6,625"],"correctOption":1,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"230e9ce3-1b40-59b2-a5af-358370dfb994","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"f90b78ff-1361-40ce-9c0e-f10ab7e4d5f6","sourceKey":"quiz:118","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) Which product line does the Laplace criterion (average of each row) recommend?","options":["Full","Full and Partial (tied)","Partial","Minimal"],"correctOption":0,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"6f44ea37-23f9-5629-b3b7-c9baa955492c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ed550871-1ea2-4967-ad10-97ca9834c43c","sourceKey":"quiz:119","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) Applying the Hurwicz criterion with α = 0.55 (Hurwicz value = α×Max + (1−α)×Min), what is Partial's Hurwicz value?","options":["₦10,100","₦11,000","₦9,675","₦11,225"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"8784afe3-0c09-5f88-8b60-aa7b983db1c7","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b1948ed0-8309-4cc6-a8f4-e52e2dcda865","sourceKey":"quiz:12","parentItemId":null,"revision":1,"payload":{"prompt":"Which formula is used to calculate future value under compound interest?","options":["FV = P/(1+r)^n","FV = P × r × n","FV = P(1+r)^n","FV = P + rn"],"correctOption":2,"section":"Section A — Basic Mathematical Concepts for Management"}},{"itemId":"4ae7d2a7-4fe7-5d7b-b8ab-4bb57d591297","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"e8d7d092-40a3-49e2-8c52-b4361baeb1fa","sourceKey":"quiz:120","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) Which product line does the Hurwicz criterion (α=0.55) recommend?","options":["Minimal","Partial","Full and Minimal (tied)","Full"],"correctOption":1,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"4bb5982f-6ef6-5ded-8b67-4347e542d099","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b28f5a0c-2b2e-4365-8e4b-e1a661730e85","sourceKey":"quiz:121","parentItemId":null,"revision":1,"payload":{"prompt":"In the Savage (Minimax Regret) method, regret for a given cell is calculated as:","options":["Row average minus column average","Column maximum minus the actual payoff in that cell","Actual payoff minus the column minimum","Row maximum minus the actual payoff"],"correctOption":1,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"04987aaf-4b7a-5004-ac92-22495660e2e8","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"98806d60-f99a-49c0-ae6b-49c2aad39b8b","sourceKey":"quiz:122","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) The column maximums are: High=20,000, Moderate=15,000, Low=6,000, Poor=18,000. What is Full's regret value in the Low market column?","options":["8,000","3,000","2,000","6,000"],"correctOption":0,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"b78b4753-96af-5cb8-b929-7d0867422df6","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"cf6c46ef-0b65-471b-8469-f85492293c91","sourceKey":"quiz:123","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) The column maximums are: High=20,000, Moderate=15,000, Low=6,000, Poor=18,000. Using the Savage (Minimax Regret) criterion, which product line is recommended?","options":["Full","Full and Partial (tied)","Minimal","Partial"],"correctOption":0,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"88912b1d-e858-5db0-9a0a-819e72f31376","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"235990f7-24e3-4eae-8e08-09357ccf0af6","sourceKey":"quiz:124","parentItemId":null,"revision":1,"payload":{"prompt":"Mr. Tiwalade, the marketing manager of a food manufacturing company, faces an uncertain market for a new product. The payoff data (₦) is as follows — Full product line: High=20,000, Moderate=15,000, Low=(2,000), Poor=4,000. Partial product line: High=20,000, Moderate=5,000, Low=1,000, Poor=500. Minimal product line: High=4,000, Moderate=(500), Low=6,000, Poor=18,000. (Bracketed figures are losses.) Which two criteria both recommend “Partial” as the best choice (Maximin picks the best worst-case; Hurwicz uses α=0.55; Laplace averages each row; Savage minimises maximum regret)?","options":["Laplace and Savage","Maximax and Laplace","Maximin and Hurwicz","Savage only SECTION H Data Analysis, Interpretation & Regression Dr. C.I. Omoera | Session 7 | 12 Questions"],"correctOption":2,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"89cc290f-9acb-5086-ac04-a5dc77e43ef0","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b7be4241-5400-4874-94b7-8d6beaa79909","sourceKey":"quiz:125","parentItemId":null,"revision":1,"payload":{"prompt":"Data analysis (as distinct from data interpretation) answers which questions?","options":["How? and What?","Who? and Which?","So what? and Why?","When? and Where?"],"correctOption":0,"section":"Section H — Data Analysis, Interpretation & Regression"}},{"itemId":"cf602aa4-634d-55ef-af85-0404d7af3084","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"aadd1bae-f19d-4cb2-945d-75616b8066be","sourceKey":"quiz:126","parentItemId":null,"revision":1,"payload":{"prompt":"Data interpretation (as distinct from data analysis) answers which questions?","options":["So what? and Why?","How? and What?","When? and Where?","Who? and Which?"],"correctOption":0,"section":"Section H — Data Analysis, Interpretation & Regression"}},{"itemId":"3343168e-7d56-52e5-827f-2d7ebb837254","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"4f1ba6b4-b4c8-4f19-89c4-d171b1a42975","sourceKey":"quiz:127","parentItemId":null,"revision":1,"payload":{"prompt":"Which is the FIRST step in the 5-Step Data Interpretation Framework?","options":["Analyse the Data","Clean and Organise the Dataset","Define Questions and Goals","Visualise and Communicate Findings"],"correctOption":2,"section":"Section H — Data Analysis, Interpretation & Regression"}},{"itemId":"1b9f6d8c-1c28-5dec-a8ab-893559a2e7ab","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"45a2bd09-6dd9-4cf3-9448-7ec41218bda0","sourceKey":"quiz:128","parentItemId":null,"revision":1,"payload":{"prompt":"In simple linear regression (ŷ = a + bx), ‘a’ represents:","options":["The correlation coefficient","The intercept — the value of y when x = 0","The predicted value of y","The slope — change in y per unit x"],"correctOption":1,"section":"Section H — Data Analysis, Interpretation & Regression"}},{"itemId":"d03b9759-e48a-509a-845c-7edeaa22ad50","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"6ac5c4d7-d9d9-4900-b7d6-93e1e509019e","sourceKey":"quiz:129","parentItemId":null,"revision":1,"payload":{"prompt":"In simple linear regression, ‘b’ represents:","options":["The slope — change in y for each 1-unit increase in x","The intercept","The predicted value ŷ","R-squared"],"correctOption":0,"section":"Section H — Data Analysis, Interpretation & Regression"}},{"itemId":"27fce025-e344-5ff9-a25c-a78847e53240","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"b43b43af-a307-41a0-b57a-fb4863dee2a1","sourceKey":"quiz:13","parentItemId":null,"revision":1,"payload":{"prompt":"A circular waste reservoir has a radius of 10m (class example, π = 3.142). What is its area?","options":["314.2 m²","628.4 m²","31.42 m²","100 m²"],"correctOption":0,"section":"Section A — Basic Mathematical Concepts for Management"}},{"itemId":"de4ecbd5-9644-5e09-ba00-66bfa06fe9c1","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"bc225b16-1181-493b-8c88-b83d87d1984d","sourceKey":"quiz:130","parentItemId":null,"revision":1,"payload":{"prompt":"If b < 0 in a regression equation, this indicates:","options":["A positive relationship","A perfect relationship","No relationship","A negative relationship — y decreases as x increases"],"correctOption":3,"section":"Section H — Data Analysis, Interpretation & Regression"}},{"itemId":"d0038c40-3d5e-5686-aa98-b7a25233558b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"075c98c8-23b4-43f5-8d6d-8f190f42936d","sourceKey":"quiz:131","parentItemId":null,"revisi