set local role authenticated;
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('40000000-0000-4000-8000-000000000015')
  where kind = 'theory_question') = $expected_content$[]$expected_content$::jsonb,
  'bua218: theory_question published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('40000000-0000-4000-8000-000000000015')
  where kind = 'model_answer') = $expected_content$[]$expected_content$::jsonb,
  'bua218: model_answer published payload and identity match source');
select ok((select coalesce(jsonb_agg(jsonb_build_object(
  'itemId', item_id, 'courseId', course_id, 'kind', kind,
  'questionId', question_id, 'sourceKey', source_key,
  'parentItemId', parent_item_id, 'revision', revision,
  'payload', payload) order by source_key collate "C"), '[]'::jsonb)
  from public.read_published_managed_content('40000000-0000-4000-8000-000000000015')
  where kind = 'rubric') = $expected_content$[]$expected_content$::jsonb,
  'bua218: rubric published payload and identity match source');

reset role;
select is((select count(*)::int from public.managed_content_items where created_by = '00000000-0000-4000-8000-000000000042'),
  3247, 'all source items carry migration provenance');
select is((select count(*)::int from public.managed_content_items where created_by = '00000000-0000-4000-8000-000000000042'
  and (current_revision <> 1 or approved_revision <> 1 or published_revision <> 1)
  and not (kind = 'cbt_question' and course_id = any (array['40000000-0000-4000-8000-000000000007', '40000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000004', '40000000-0000-4000-8000-000000000001']::uuid[]))),
  0, 'all live repository items outside the imported banks are approved and published at revision one');
select is((select count(*)::int from public.managed_content_reviews where reviewed_by = '00000000-0000-4000-8000-000000000042'
  and decision = 'rejected'), 0, 'migration never publishes a rejected revision');
select is((select count(*)::int from public.managed_content_items i
  join public.managed_content_items parent on parent.id = i.parent_item_id
  where i.created_by = '00000000-0000-4000-8000-000000000042' and i.kind = 'model_answer'
    and i.published_parent_revision is distinct from parent.published_revision),
  0, 'every published model answer binds the published theory revision');
select is((select count(*)::int from public.managed_content_items where created_by = '00000000-0000-4000-8000-000000000042'
  and kind = 'rubric'), 0, 'no source rubric was fabricated');
select * from finish();
rollback;
